estyle/664209"},{"title":"ไทยรัฐ (ข้อมูล ททท.): ต้นเทียนประเภทแกะสลัก ติดพิมพ์ โบราณ","url":"https://www.thairath.co.th/lifestyle/travel/2947403"},{"title":"TrueID: ต้นเทียนตกแต่งเป็นเรื่องราวพุทธประวัติ","url":"https://travel.trueid.net/detail/6BDWqAnNQ3j8"},{"title":"เดลินิวส์: งานแห่เทียนพรรษา อ.ประโคนชัย จ.บุรีรัมย์","url":"https://www.dailynews.co.th/articles/3642428/"}]},"schedule_date":null,"verified_by":null,"verified_at":null,"note":"ร่าง — ข้อมูลค้นจากแหล่งที่ระบุ รอทีมตรวจทานก่อนเผยแพร่จริง","status":"draft","published_at":null}$j$::jsonb),
